:root {
  --cream: #f2e8d5;
  --brown-dark: #3b2410;
  --brown-mid: #7a4e2d;
  --red-wax: #8b1a1a;
  --gold: #c9a84c;
  --divider: #c4a97d;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.seal-tag {
  background-color: var(--cream);
  border: 2px solid var(--brown-mid);
  border-radius: 6px 6px 4px 4px;
  width: 200px;
  padding: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.tag-header {
  background-color: var(--brown-dark);
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 12px;
  border-radius: 4px 4px 0 0;
  box-sizing: border-box;
}

.tag-label {
  color: var(--gold);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
}

.tag-number {
  color: var(--divider);
  font-size: 11px;
  font-weight: 400;
}

.seal-display {
  padding: 16px 0 10px;
}

.seal-circle {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background-color: var(--red-wax);
  border: 3px solid var(--brown-mid);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
}

.tag-details {
  width: 100%;
  padding: 0 14px 10px;
  box-sizing: border-box;
  border-top: 1px solid var(--divider);
  margin-top: 2px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 6px 0 0;
}

.detail-key {
  color: var(--brown-mid);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.detail-val {
  color: var(--brown-dark);
  font-size: 12px;
  font-weight: 700;
}

.tag-footer {
  width: 100%;
  border-top: 1px solid var(--divider);
  text-align: center;
  padding: 6px 0;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--brown-mid);
  border-radius: 0 0 4px 4px;
}
